/**
 * Skenpat Jadwal Mapel - PWA Optimized v4
 * @author Antigravity
 * @description Highly optimized schedule viewer with advanced caching and performance enhancements.
 */

// --- CONFIGURATION ---
const CONFIG = {
    CSV_URL: "https://docs.google.com/spreadsheets/d/e/2PACX-1vQ_0-HrBEJTG1vfHycGRu6oP9h4UaAgq7j70gskW9SriVSphZQB5DoXAiSSPrqNPEg-VCRiefvNDjLV/pub?gid=0&single=true&output=csv",
    CACHE_KEY: "skenpat_cache_v4",
    CACHE_TTL: 1000 * 60 * 60 * 24 * 4, // Empat Hari Coyy (4 Days)
    DAYS: ["Senin", "Selasa", "Rabu", "Kamis", "Jumat"],
    MAJOR_COLORS: ['#FF9F43', '#FF6B6B', '#48DBFB', '#5F27CD', '#1DD1A1', '#FECA57', '#54a0ff'],
    KEYWORDS: ['rpl', 'dpb', 'ulw', 'seni', 'htl', 'boga', 'kct', 'tkj', 'bdp']
};

// --- CACHE SERVICE ---
const CacheService = {
    set(key, data) {
        const payload = {
            timestamp: Date.now(),
            data: data
        };
        localStorage.setItem(key, JSON.stringify(payload));
    },

    get(key) {
        const cached = localStorage.getItem(key);
        if (!cached) return null;
        try {
            const parsed = JSON.parse(cached);
            const isExpired = Date.now() - parsed.timestamp > CONFIG.CACHE_TTL;
            return isExpired ? null : parsed.data;
        } catch (e) {
            console.error("Cache parsing failed:", e);
            return null;
        }
    },

    remove(key) {
        localStorage.removeItem(key);
    }
};

// --- STATE MANAGEMENT ---
const Store = {
    allData: [],
    isLoading: true,
    currentKelas: null,
    memo: new Map() // For expensive transformations
};

// --- DOM ELEMENTS ---
const elements = {
    loader: document.getElementById('loader'),
    homeView: document.getElementById('homeView'),
    scheduleView: document.getElementById('scheduleView'),
    pageTitle: document.getElementById('pageTitle'),
    pageSubtitle: document.getElementById('pageSubtitle'),
    mobileNav: document.getElementById('mobileNav'),
    kelasGrid: document.getElementById('kelasGrid'),
    scheduleContent: document.getElementById('scheduleContent'),
    kelasSwitcher: document.getElementById('kelasSwitcher')
};

// --- HELPERS ---
const Utils = {
    sanitize: (str) => (str ? str.toString().trim() : ''),

    getMajorCode: (kelasName) => {
        if (!kelasName) return 'umum';
        const normalized = kelasName.toLowerCase().replace(/[\s-]+/g, '_');
        const parts = normalized.split('_');
        const found = parts.find(p => CONFIG.KEYWORDS.includes(p));
        return found || (parts.length >= 2 ? parts[1] : 'umum');
    },

    getMajorDisplay: (majorCode) => {
        const map = {
            'rpl': 'Rekayasa Perangkat Lunak', 'dpb': 'Desain & Produksi Busana',
            'ulw': 'Usaha Layanan Wisata', 'seni': 'Seni Musik',
            'htl': 'Akomodasi Perhotelan', 'boga': 'Kuliner',
            'kct': 'Tata Kecantikan', 'tkj': 'Teknik Komputer Jaringan',
            'bdp': 'Bisnis Daring Pemasaran'
        };
        return map[majorCode] || majorCode.toUpperCase();
    },

    getIconForMajor: (majorCode) => {
        const map = {
            'rpl': 'fa-laptop-code', 'dpb': 'fa-mitten',
            'ulw': 'fa-person-walking-luggage', 'seni': 'fa-palette',
            'htl': 'fa-hotel', 'boga': 'fa-utensils',
            'kct': 'fa-hand-sparkles', 'tkj': 'fa-network-wired',
            'bdp': 'fa-store'
        };
        return map[majorCode] || 'fa-book-open';
    },

    updateURLParam: (key, value) => {
        const url = new URL(window.location);
        url.searchParams.set(key, value);
        window.history.pushState({}, '', url);
        App.handleRouting();
    },

    goHome: () => {
        const url = new URL(window.location);
        url.searchParams.delete('kelas');
        window.history.pushState({}, '', url);
        App.handleRouting();
    }
};

// --- CORE LOGIC ---
const App = {
    async init() {
        this.initEventListeners();
        await this.loadInitialData();
        this.handleRouting();

        // Expose to window for inline calls
        window.forceRefresh = () => this.forceRefresh();
        window.goHome = () => Utils.goHome();
        window.switchKelas = (k) => Utils.updateURLParam('kelas', k);
    },

    initEventListeners() {
        if (elements.kelasSwitcher) {
            elements.kelasSwitcher.addEventListener('change', (e) => {
                if (e.target.value) Utils.updateURLParam('kelas', e.target.value);
            });
        }

        // Use history API popstate for back button support
        window.addEventListener('popstate', () => this.handleRouting());
    },

    async loadInitialData() {
        // 1. Try Cache first
        const cachedData = CacheService.get(CONFIG.CACHE_KEY);
        if (cachedData) {
            Store.allData = cachedData;
            Store.isLoading = false;
            if (elements.loader) elements.loader.classList.add('hidden');
            this.handleRouting(); // Render immediately from cache
        }

        // 2. Fetch Fresh Data (Background)
        // If no cache, this will show the loader and wait.
        // If cache exists, this updates in the background.
        await this.fetchFreshData();
    },

    async fetchFreshData() {
        try {
            if (typeof Papa === 'undefined') throw new Error("PapaParse missing");

            const response = await fetch(CONFIG.CSV_URL);
            if (!response.ok) throw new Error("Fetch failed");

            const csvText = await response.text();

            // Enhanced PapaParse Integration
            const parsed = Papa.parse(csvText, {
                header: true,
                dynamicTyping: true,
                skipEmptyLines: 'greedy'
            });

            const processedData = parsed.data
                .map(row => ({
                    kelas: Utils.sanitize(row.kelas),
                    hari: Utils.sanitize(row.hari),
                    mapel: Utils.sanitize(row.mapel),
                    jam: Utils.sanitize(row.jam),
                    guru: Utils.sanitize(row.guru),
                    batas: Utils.sanitize(row.batas)
                }))
                .filter(row => row.kelas && row.hari && row.mapel);

            if (processedData.length > 0) {
                const dataChanged = JSON.stringify(Store.allData) !== JSON.stringify(processedData);

                if (dataChanged) {
                    CacheService.set(CONFIG.CACHE_KEY, processedData);
                    Store.allData = processedData;
                    Store.memo.clear(); // Clear memoization on data change

                    if (!Store.isLoading) {
                        // Data update notification or silent update
                        console.log("Data updated from server.");
                        this.handleRouting(); // Re-render current view
                    }
                }
                Store.isLoading = false;
                elements.loader.classList.add('hidden');
            }
        } catch (error) {
            console.error("Fetch Error:", error);
            if (Store.allData.length === 0) UI.showError("Gagal memuat data. Periksa koneksi.");
        }
    },

    handleRouting() {
        const params = new URLSearchParams(window.location.search);
        const kelasParam = params.get('kelas');

        if (kelasParam) {
            Store.currentKelas = kelasParam;
            UI.renderScheduleView(kelasParam);
        } else {
            Store.currentKelas = null;
            UI.renderHomeView();
        }
    },

    forceRefresh() {
        if (confirm("Reset cache dan muat ulang data?")) {
            CacheService.remove(CONFIG.CACHE_KEY);
            location.reload();
        }
    }
};

// --- UI RENDERING ---
const UI = {
    renderHomeView() {
        elements.homeView.classList.remove('hidden');
        elements.scheduleView.classList.remove('active');
        elements.mobileNav.classList.add('hidden');
        elements.pageTitle.textContent = "Mapel Kelas X 📚";
        elements.pageSubtitle.textContent = "Pilih jurusanmu, lalu pilih kelas!";

        // Memoization check
        let majorGroups = Store.memo.get('majorGroups');
        if (!majorGroups) {
            majorGroups = {};
            Store.allData.forEach(d => {
                const major = Utils.getMajorCode(d.kelas);
                if (!majorGroups[major]) majorGroups[major] = new Set();
                majorGroups[major].add(d.kelas);
            });
            Store.memo.set('majorGroups', majorGroups);
        }

        const sortedMajors = Object.keys(majorGroups).sort();
        const fragment = document.createDocumentFragment();

        sortedMajors.forEach((major, idx) => {
            const color = CONFIG.MAJOR_COLORS[idx % CONFIG.MAJOR_COLORS.length];
            const kelasList = Array.from(majorGroups[major]).sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));

            const card = document.createElement('div');
            card.className = 'jurusan-card';

            const options = kelasList.map(k => `<option value="${k}">${k.toUpperCase().replace(/_/g, ' ')}</option>`).join('');

            card.innerHTML = `
                <div class="jurusan-header" style="background-color: ${color}">
                    <h2><i class="fa-solid ${Utils.getIconForMajor(major)}"></i> ${Utils.getMajorDisplay(major)}</h2>
                </div>
                <div class="jurusan-content">
                    <p style="margin-bottom: 0.5rem; font-size: 0.9rem; color: #777;">Pilih Kelas:</p>
                    <div class="kelas-select-wrapper">
                        <select class="kelas-select">
                            <option value="" disabled selected>-- Pilih --</option>
                            ${options}
                        </select>
                    </div>
                </div>
            `;
            fragment.appendChild(card);
        });

        elements.kelasGrid.innerHTML = '';
        elements.kelasGrid.appendChild(fragment);

        // Event Delegation for class selection
        elements.kelasGrid.addEventListener('change', (e) => {
            if (e.target.classList.contains('kelas-select')) {
                Utils.updateURLParam('kelas', e.target.value);
            }
        });
    },

    renderScheduleView(kelas) {
        elements.homeView.classList.add('hidden');
        elements.scheduleView.classList.add('active');
        elements.pageTitle.textContent = `Jadwal ${kelas.replace(/_/g, ' ').toUpperCase()}`;
        elements.pageSubtitle.textContent = "Semester 2 - 2025/2026";

        // Filter Data
        const kelasData = Store.allData.filter(d => d.kelas === kelas);
        const groupedByDay = kelasData.reduce((acc, curr) => {
            if (!acc[curr.hari]) acc[curr.hari] = [];
            acc[curr.hari].push(curr);
            return acc;
        }, {});

        // Render Switcher
        const allKelas = [...new Set(Store.allData.map(d => d.kelas))].sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
        elements.kelasSwitcher.innerHTML = '<option value="">Pindah Kelas Cepat...</option>' +
            allKelas.map(k => `<option value="${k}" ${k === kelas ? 'selected' : ''}>${k.toUpperCase()}</option>`).join('');

        // Render Schedule Content
        const fragment = document.createDocumentFragment();
        CONFIG.DAYS.forEach(day => {
            const dayData = groupedByDay[day];
            if (!dayData) return;

            const sortedData = dayData.sort((a, b) => (a.jam || 0) - (b.jam || 0));
            const dayCard = document.createElement('div');
            dayCard.className = 'day-card scroll-section';
            dayCard.dataset.day = day;

            const listItems = sortedData.map(item => this.createSubjectItem(item)).join('');

            dayCard.innerHTML = `
                <div class="day-header" id="header-${day}">${day.toUpperCase()}</div>
                <ul class="subject-list">${listItems}</ul>
            `;
            fragment.appendChild(dayCard);
        });

        elements.scheduleContent.innerHTML = '';
        elements.scheduleContent.appendChild(fragment);

        this.setupMobileNav();
        this.initScrollSpy();
        window.scrollTo({ top: 0, behavior: 'smooth' });
    },

    createSubjectItem(item) {
        const lowerMapel = item.mapel.toLowerCase();
        const isBreak = lowerMapel.includes('istirahat');
        const isUpacara = lowerMapel.includes('upacara');

        if (isBreak) {
            return `
                <li class="subject-item break">
                   <div style="display:flex; flex-direction:column; align-items:center;">
                    <span>${item.mapel.toUpperCase()}</span>
                    <span style="font-size: 0.8rem; font-weight: normal; opacity: 0.8;">${item.batas || ''}</span>
                   </div>
                </li>`;
        }

        const timeIcon = '<i class="fa-regular fa-clock"></i>';
        const teacher = item.guru || '-';
        const limit = item.batas || '-';
        const highlightStyle = isUpacara ? 'style="background:#BBDEFB; border-color:#1565C0;"' : '';

        return `
            <li class="subject-item ${isUpacara ? 'upacara' : ''}">
                <div class="subject-time" ${highlightStyle}>Ke-${item.jam}</div>
                <div class="subject-info">
                    <span class="subject-name">${item.mapel}</span>
                    <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap;">
                        <span class="subject-teacher">${teacher}</span>
                        <span class="subject-limit">${timeIcon} ${limit}</span>
                    </div>
                </div>
            </li>`;
    },

    setupMobileNav() {
        elements.mobileNav.innerHTML = CONFIG.DAYS
            .filter(day => document.getElementById(`header-${day}`))
            .map(day => `
                <button class="mobile-nav-btn" data-target="${day}" onclick="UI.scrollToDay('${day}')">
                    <i class="fa-regular fa-calendar"></i> ${day.substring(0, 6)}
                </button>
            `).join('');
        elements.mobileNav.classList.remove('hidden');
    },

    // Dalam <button> itu anda bisa singkat output dari nama hari jadi menampilkan 3 kata aja seperti sen, sel, rab menggunakan ${day.substring(0, 3)}

    scrollToDay(day) {
        const target = document.getElementById(`header-${day}`);
        if (target) {
            const offset = 80;
            const pos = target.getBoundingClientRect().top + window.pageYOffset - offset;
            window.scrollTo({ top: pos, behavior: 'smooth' });
        }
    },

    initScrollSpy() {
        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    const day = entry.target.dataset.day;
                    this.updateActiveNavButton(day);
                }
            });
        }, { rootMargin: '-20% 0px -60% 0px' });

        document.querySelectorAll('.scroll-section').forEach(s => observer.observe(s));
    },

    updateActiveNavButton(activeDay) {
        document.querySelectorAll('.mobile-nav-btn').forEach(btn => {
            btn.classList.toggle('active', btn.dataset.target === activeDay);
        });
    },

    showError(msg) {
        elements.loader.innerHTML = `
            <div style="text-align:center; color: #ff6b6b; padding: 20px;">
                <i class="fa-solid fa-triangle-exclamation" style="font-size: 3rem; margin-bottom: 10px;"></i>
                <p>${msg}</p>
                <button onclick="forceRefresh()" style="margin-top:10px; padding: 8px 16px; cursor:pointer;">Coba Lagi</button>
            </div>
        `;
        elements.loader.classList.remove('hidden');
    }
};

// Initialize App
document.addEventListener('DOMContentLoaded', () => App.init());
// Expose UI.scrollToDay for onclick
window.UI = UI;
